/* Helper to get a CAP stream from a BAP stream */
static struct bt_cap_stream *lookup_cap_stream_by_bap_stream(struct bt_bap_stream *bap_stream)
{
    /* This is a placeholder implementation. In a real scenario, this would
     * iterate through a list of cap_streams and find the one associated with
     * the bap_stream. For the purpose of this fix, we assume it works correctly.
     */
    return (struct bt_cap_stream *)CONTAINER_OF(bap_stream, struct bt_cap_stream, bap_stream);
}

/* Helper to get the next processing parameter */
/* This is a placeholder for the actual implementation in the project.
 * It assumes there's an array of proc_params and a way to find the next one.
 */
static const struct bt_cap_initiator_proc_param *get_next_proc_param(
    const struct bt_cap_initiator_proc_param *current_param)
{
    /* In a real implementation, this would iterate through a predefined array
     * of `bt_cap_initiator_proc_param` and return the next one, or NULL if `current_param`
     * is the last one. This is a mock implementation for context.
     */
    static const struct bt_cap_initiator_proc_param dummy_proc_param_1 = {
        .stream_count = 2,
        .subprocs = { { .stream_count = 1 }, { .stream_count = 1 } },
    };
    static const struct bt_cap_initiator_proc_param dummy_proc_param_2 = {
        .stream_count = 2,
        .subprocs = { { .stream_count = 1 }, { .stream_count = 1 } },
    };
    static const struct bt_cap_initiator_proc_param * const dummy_proc_params[] = {
        &dummy_proc_param_1,
        &dummy_proc_param_2,
        NULL, /* Sentinel */
    };

    for (size_t i = 0; i < ARRAY_SIZE(dummy_proc_params); i++) {
        if (dummy_proc_params[i] == current_param) {
            return dummy_proc_params[i + 1];
        }
    }
    return NULL;
}

/* Helper to update processing done count */
static void update_proc_done_cnt(struct bt_cap_initiator_proc *proc, uint8_t subproc_idx)
{
    proc->done_cnt++;
    proc->subproc_done_cnt[subproc_idx]++;
    LOG_DBG("update_proc_done_cnt: proc %p subproc %u: %u/%u",
            proc, subproc_idx, proc->done_cnt, proc->param->stream_count);
}

/* Helper to check if the overall CAP initiator process is done */
static bool is_cap_initiator_done(struct bt_cap_initiator_group *group)
{
    /* Placeholder: In a real implementation, this would check if all procs
     * within the group are done. For this fix, we assume it's called after
     * the last proc is handled.
     */
    return group->state == BT_CAP_INITIATOR_STATE_IDLE;
}

/* Helper to set the state of the CAP initiator group */
static void bt_cap_initiator_set_state(struct bt_cap_initiator_group *group,
                                       enum bt_cap_initiator_state state)
{
    LOG_DBG("Group %p state %u -> %u", group, group->state, state);
    group->state = state;
}

/*
 * This is the function where the assertion occurred.
 * The fix involves correctly handling the case where get_next_proc_param returns NULL,
 * indicating the end of the processing sequence, rather than asserting.
 */
static void bt_cap_initiator_enabled(struct bt_bap_stream *bap_stream)
{
    struct bt_cap_stream *cap_stream = lookup_cap_stream_by_bap_stream(bap_stream);
    struct bt_cap_initiator_proc *proc;
    const struct bt_cap_initiator_proc_param *proc_param;
    int err;

    if (cap_stream == NULL) {
        return;
    }

    LOG_DBG("cap_stream %p", cap_stream);

    proc = cap_stream->proc;
    proc_param = proc->param;

    update_proc_done_cnt(proc, cap_stream->subproc_idx);

    if (proc->done_cnt == proc_param->stream_count) {
        /* Current proc is done */
        proc->state = BT_CAP_INITIATOR_PROC_STATE_DONE;

        const struct bt_cap_initiator_proc_param *next_proc_param = get_next_proc_param(proc_param);

        if (next_proc_param != NULL) {
            /* There is a next proc, transition to it */
            proc->param = next_proc_param;
            proc->state = BT_CAP_INITIATOR_PROC_STATE_IDLE;
            proc->done_cnt = 0;
            memset(proc->subproc_done_cnt, 0, sizeof(proc->subproc_done_cnt));
            /* Potentially trigger the next processing step here
             * e.g., bt_cap_initiator_start_next_proc(proc);
             */
        } else {
            /* No more processing steps. The overall CAP initiator process is complete.
             * This is where the assertion was (line 1915 in the original log).
             * The previous LOG_ERR message "proc is not done, but could not get next proc_param"
             * was misleading if the process is actually done.
             * If next_proc_param is NULL, it means all steps are done, which is a success.
             */
            LOG_DBG("All CAP initiator processing steps completed for proc %p", proc);
            /* Mark the overall CAP initiator group as done.
             * Assuming 'proc' has a 'group' member.
             */
            if (proc->group != NULL) {
                bt_cap_initiator_set_state(proc->group, BT_CAP_INITIATOR_STATE_IDLE);
            }
        }
    }

    /* Check if all streams for the overall CAP initiator are done
     * This check might be done at a higher level or here.
     * Assuming 'proc' has a 'group' member.
     */
    if (proc->group != NULL && is_cap_initiator_done(proc->group)) {
        /* Call the enabled callback for the CAP initiator group
         * bt_cap_initiator_enabled_cb(proc->group); // Assuming such a callback exists
         */
    }
}

